keys = input().split()
values = [int(x) for x in input().split()]
mapping = {}
for k, v in zip(keys, values):
    mapping[k] = v
for k, v in mapping.items():
    print(f"{k}: {v}")

def fmt(s):
    return " ".join(str(x) for x in sorted(s)) if s else "Empty"

a = {int(x) for x in input().split()}
b = {int(x) for x in input().split()}
print(f"Union: {fmt(a | b)}")
print(f"Intersection: {fmt(a & b)}")
print(f"Difference: {fmt(a - b)}")

words = input().lower().split()
freq = {}
for w in words:
    freq[w] = freq.get(w, 0) + 1
for w in sorted(freq):
    print(f"{w}: {freq[w]}")

n = int(input())
prices = {}
for _ in range(n):
    name, cost = input().split()
    prices[name] = int(cost)
max_k = min_k = None
max_v = min_v = 0
for k, v in prices.items():
    if max_k is None or v > max_v:
        max_k, max_v = k, v
    if min_k is None or v < min_v:
        min_k, min_v = k, v
print(f"Max: {max_k} ({max_v}), Min: {min_k} ({min_v})")

def read_dict():
    count = int(input())
    d = {}
    for _ in range(count):
        k, v = input().split()
        d[k] = d.get(k, 0) + int(v)
    return d

d1 = read_dict()
d2 = read_dict()
merged = dict(d1)
for k, v in d2.items():
    merged[k] = merged.get(k, 0) + v
for k in sorted(merged):
    print(f"{k}: {merged[k]}")

nums = [int(x) for x in input().split()]
seen = set()
dups = set()
for x in nums:
    if x in seen:
        dups.add(x)
    else:
        seen.add(x)
if not dups:
    print("None")
else:
    print(" ".join(str(x) for x in sorted(dups)))

a = {int(x) for x in input().split()}
b = {int(x) for x in input().split()}
if a == b:
    print("Equal")
elif a.issubset(b):
    print("A Subset of B")
elif b.issubset(a):
    print("B Subset of A")
elif a.isdisjoint(b):
    print("Disjoint")
else:
    print("Partial Overlap")

n = int(input())
groups = {}
for _ in range(n):
    name, grade = input().split()
    groups.setdefault(grade, []).append(name)
for grade in sorted(groups):
    names = ", ".join(sorted(groups[grade]))
    print(f"{grade}: {names}")

a = {int(x) for x in input().split()}
b = {int(x) for x in input().split()}
sym = (a - b) | (b - a)
if sym:
    print(" ".join(str(x) for x in sorted(sym)))
else:
    print("Empty")

words = input().lower().split()
index = {}
for w in words:
    index.setdefault(w[0], set()).add(w)
for ch in sorted(index):
    print(f"{ch}: {' '.join(sorted(index[ch]))}")

words = input().split()
groups = {}
for w in words:
    sig = tuple(sorted(w))
    groups.setdefault(sig, []).append(w)
for group in groups.values():
    print(" ".join(sorted(group)))

n = int(input())
stock = {}
for _ in range(n):
    item, q = input().split()
    stock[item] = stock.get(item, 0) + int(q)

m = int(input())
for _ in range(m):
    cmd, item, q = input().split()
    qty = int(q)
    if cmd == "ADD":
        stock[item] = stock.get(item, 0) + qty
    elif cmd == "SELL":
        if stock.get(item, 0) >= qty:
            stock[item] -= qty

for item in sorted(stock):
    print(f"{item}: {stock[item]}")

nums = [int(x) for x in input().split()]
num_set = set(nums)
best = 0
for x in num_set:
    if (x - 1) not in num_set:
        cur = x
        while (cur + 1) in num_set:
            cur += 1
        length = cur - x + 1
        if length > best:
            best = length
print(best)
